Scenarios.Scenario:
**Ext4 precondition and whole-population probe (2026-09-23, Linux, Bun 1.3.14).** A loopback
ext4 image is a precondition; XFS does not reproduce the recycling (0/100 and 0/200 measured),
so an XFS green is not ext4 evidence. Create and mount it:

sudo mkdir -p /var/mnt/ext4t
sudo dd if=/dev/zero of=/var/tmp/ext4.img bs=1M count=256
sudo mkfs.ext4 -q -F /var/tmp/ext4.img
sudo mount -o loop /var/tmp/ext4.img /var/mnt/ext4t
sudo chmod 777 /var/mnt/ext4t

Save the probe as `PROBE_DIR/inode-recycle-probe.mjs` (PROBE_DIR is its host directory) and run it with TMPDIR on the mount:

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
const N = 300;
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "inode-probe-"));
const f = path.join(dir, "a");
function fileRound(pin) {
  let recycled = 0;
  for (let i = 0; i !== N; i += 1) {
    fs.writeFileSync(f, "x");
    let fd;
    if (pin) { fd = fs.openSync(f, "r"); }
    const ino = pin ? fs.fstatSync(fd).ino : fs.statSync(f).ino;
    fs.unlinkSync(f);
    fs.writeFileSync(f, "x");
    if (fs.statSync(f).ino === ino) { recycled += 1; }
    fs.unlinkSync(f);
    if (pin) { fs.closeSync(fd); }
  }
  return recycled;
}
function dirRound(pin) {
  let recycled = 0;
  const d = path.join(dir, pin ? "cand-pin" : "cand");
  for (let i = 0; i !== N; i += 1) {
    fs.mkdirSync(d);
    let fd;
    if (pin) { fd = fs.openSync(d, "r"); }
    const ino = pin ? fs.fstatSync(fd).ino : fs.statSync(d).ino;
    fs.rmdirSync(d);
    fs.mkdirSync(d);
    if (fs.statSync(d).ino === ino) { recycled += 1; }
    fs.rmdirSync(d);
    if (pin) { fs.closeSync(fd); }
  }
  return recycled;
}
const report = {
  n: N,
  filesystem: fs.statfsSync(dir).type,
  fileRecycledUnpinned: fileRound(false),
  dirRecycledUnpinned: dirRound(false),
  fileRecycledPinned: fileRound(true),
  dirRecycledPinned: dirRound(true),
};
console.log(JSON.stringify(report));
fs.rmSync(dir, { recursive: true, force: true });

Command (mount the probe directory and the ext4 mount into the container):

podman run --rm --security-opt label=disable -v PROBE_DIR:/probes -v /var/mnt/ext4t:/ext4 -e TMPDIR=/ext4 docker.io/oven/bun:1.3.14 bun /probes/inode-recycle-probe.mjs

Observed output, exit 0:

{"n":300,"filesystem":61267,"fileRecycledUnpinned":300,"dirRecycledUnpinned":300,
 "fileRecycledPinned":0,"dirRecycledPinned":0}

`filesystem` 61267 is 0xEF53 (ext4). Without a pin the file and the directory inode numbers
recycle in every case; with the handle held open they never do, which is the mechanism the
repair relies on.
Cleanup after the probe: `sudo umount /var/mnt/ext4t && sudo rm /var/tmp/ext4.img`.
